export interface Empty {}
export interface Data { id: string; }
export interface Value { event: Empty | Data | null; }
export type EmptyAlias = Empty;
export interface AliasedValue { event: EmptyAlias | Data; }
export interface Callable { (): string; }
export interface Indexed { [key: string]: string; }
export interface Inherited extends Data {}
export interface Generic<T> {}
export interface Controls {
    callable: Callable | Data;
    indexed: Indexed | Data;
    inherited: Inherited | string;
    generic: Generic<string> | Data;
}
